style.css:
@-moz-document domain("sainsburys.co.uk"), domain("groceries.sainsburys.co.uk") {
/* Base page */
  html, body {
    background: #111 !important;
    color: #f5f5f5 !important;
  }

  /* Generic containers */
  body, 
  main,
  .content,
  .page,
  .wrapper,
  .container {
    background: #111 !important;
    color: #f5f5f5 !important;
  }

  /* Header & nav */
  header,
  .header,
  .site-header,
  nav,
  .nav,
  .global-header {
    background: #181818 !important;
    color: #f5f5f5 !important;
    border-color: #333 !important;
  }

  /* Footer */
  footer,
  .footer,
  .site-footer {
    background: #101010 !important;
    color: #cccccc !important;
    border-top: 1px solid #333 !important;
  }

  /* Links */
  a {
    color: #ff8c00 !important; /* Sainsbury-ish orange */
  }

  a:hover,
  a:focus {
    color: #ffb347 !important;
  }

  /* Headings */
  h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
  }

  /* Product tiles / cards */
  .product,
  .product-tile,
  .productTile,
  .product-card,
  .productCard,
  .sku-tile,
  .sku-tile__container {
    background: #181818 !important;
    color: #f5f5f5 !important;
    border-color: #333 !important;
  }

  .product-title,
  .product-name,
  .sku-tile__title {
    color: #ffffff !important;
  }

  .price,
  .product-price,
  .sku-tile__price {
    color: #ffb347 !important;
  }

  /* Panels, modals, dropdowns */
  .panel,
  .modal,
  .dialog,
  .dropdown-menu,
  .popover {
    background: #181818 !important;
    color: #f5f5f5 !important;
    border-color: #333 !important;
  }

  /* Forms */
  input,
  select,
  textarea {
    background: #1b1b1b !important;
    color: #f5f5f5 !important;
    border: 1px solid #444 !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #888 !important;
  }

  /* Buttons */
  button,
  .btn,
  .button {
    background: #ff8c00 !important;
    color: #111 !important;
    border: 1px solid #ff8c00 !important;
  }

  button:hover,
  .btn:hover,
  .button:hover {
    background: #ffb347 !important;
    border-color: #ffb347 !important;
  }

  /* Tables (e.g. order history) */
  table {
    background: #111 !important;
    color: #f5f5f5 !important;
  }

  th, td {
    border-color: #333 !important;
  }

  th {
    background: #181818 !important;
  }

  tr:nth-child(even) {
    background: #151515 !important;
  }

  tr:nth-child(odd) {
    background: #101010 !important;
  }

  /* Banners / promos */
  .banner,
  .promo,
  .promotion {
    background: #181818 !important;
    color: #f5f5f5 !important;
  }

  /* Icons or images that look inverted in dark mode */
  img,
  svg {
    filter: none !important;
  }

  /* If any logos or icons disappear, you can selectively invert them:
  .some-logo-class img {
    filter: invert(1) hue-rotate(180deg) !important;
  }
  */

  /* Remove harsh white backgrounds that slip through */
  * {
    background-color: transparent;
  }
}
